//! Small prerequisite lessons between the original larger tasks.
use crate::lessons::Lesson;
use makine_lang::tr;

pub fn all() -> Vec<Lesson> {
    vec![
    Lesson{id:"register",title:tr!("Register ve sabit", "Registers and constants"),
        about:tr!("Program, üstten aşağı komutlar yürütür. Register işlemcinin içindeki çalışma alanıdır. li a0,42, a0'ın eski değerini 42 ile değiştirir; 42 bir adres değildir. x0 daima 0'dır. ebreak bu makinede programı durdurur. İlk denemede Derle, Baştan yükle, Bir komut sırasını izle.","A program executes instructions in order. A register is working storage inside the CPU. li a0,42 replaces a0's old value with 42; 42 is not an address. x0 is always 0. ebreak stops this machine. Try Build, Load from start, One instruction."),
        predict:tr!("li a0,7 ardından li a0,42: a0 kaç?", "li a0,7 followed by li a0,42: what is a0?"),answer:"42",
        change:tr!("42 yerine 0x2A yaz; aynı bitleri onluk ve hex izle.","Replace 42 with 0x2A; compare decimal and hex views."),
        task:tr!("Başlangıç değeri ne olursa olsun a0'a 42 yükle ve dur.","Regardless of its initial value, load 42 into a0 and stop."),
        example:"li a0, 7\nli a0, 42\nebreak\n",starter:"# a0 = 42\n\nebreak\n",solution:"li a0,42\nebreak\n",
        hint:tr!("li hedef,sayı. Virgülden sonra register değil sayı var.","li destination,number. After the comma comes a number, not a register.")},
    Lesson{id:"copy",title:tr!("Değeri kopyala", "Copy a value"),
        about:tr!("mv a0,a1, a1'in değerini a0'a kopyalar; a1'i değiştirmez. Hedef önce, kaynak sonra yazılır. mv bir kısa yazımdır; assembler bunu addi a0,a1,0 yapabilir. Bir register'dan diğerine kopyalamak RAM okuması değildir.","mv a0,a1 copies a1's value to a0 without changing a1. Destination comes first. mv is shorthand; the assembler may emit addi a0,a1,0. Copying a register is not a RAM read."),
        predict:tr!("a0=3,a1=9 iken mv a0,a1 sonrası a1?", "With a0=3,a1=9, what is a1 after mv a0,a1?"),answer:"9",
        change:tr!("Kaynak ve hedefi ters çevir; hangisi değişiyor?", "Swap source and destination; which one changes?"),
        task:tr!("a1'i değiştirmeden değerini a0'a kopyala.","Copy a1 to a0 without changing a1."),
        example:"li a0,3\nli a1,9\nmv a0,a1\nebreak\n",starter:"# a0 = a1; preserve a1\n\nebreak\n",solution:"mv a0,a1\nebreak\n",
        hint:tr!("mv a0,a1 veya addi a0,a1,0 kullanabilirsin.","Use mv a0,a1 or addi a0,a1,0.")},
    Lesson{id:"shift",title:tr!("Kaydırma ve taşma", "Shifts and wrapping"),
        about:tr!("Bir bit sola kaydırmak ikiyle, iki bit sola kaydırmak dörtle çarpmaya eşdeğerdir. Register 32 bit: dışarı taşan bitler kaybolur, sonuç mod 2^32 olur. 0x40000000 iki sola kayınca 0 olur. srli üstten 0, srai işaret biti ekler; negatif sayıda farkı gör.","Shifting left by one is multiplication by two; by two, multiplication by four. Registers hold 32 bits: shifted-out bits are lost, so results wrap modulo 2^32. 0x40000000 shifted left twice becomes 0. srli fills with zero; srai with the sign bit."),
        predict:"3 << 2 = ?",answer:"12",change:tr!("Negatif bir sayıda srli ve srai sonuçlarını karşılaştır.","Compare srli and srai for a negative number."),
        task:tr!("a0'ı dört katına çıkar; 32-bit taşma davranışını koru.","Multiply a0 by four, preserving 32-bit wrapping."),
        example:"li a0,3\nslli a0,a0,2\nebreak\n",starter:"# a0 *= 4\n\nebreak\n",solution:"slli a0,a0,2\nebreak\n",hint:tr!("slli a0,a0,2. add ile de doğru çözebilirsin.","slli a0,a0,2. Correct add-based solutions also work.")},
    Lesson{id:"unsigned",title:tr!("Aynı bitler, işaretsiz sayılar", "Same bits, unsigned numbers"),
        about:tr!("0xFFFFFFFF işaretli -1, işaretsiz 4294967295'tir. Donanım aynı bitleri tutar; karşılaştırma komutu yorumu seçer. bltu/bgeu işaretsiz, blt/bge işaretlidir. Önceki maksimum görevinde negatif doğruydu; burada adresler ve ham 32-bit sayılar gibi işaretsiz karşılaştırma yapacağız.","0xFFFFFFFF is signed -1 or unsigned 4294967295. The hardware holds the same bits; the comparison selects their interpretation. bltu/bgeu are unsigned, blt/bge signed. The preceding maximum task used signed numbers; now compare raw 32-bit values like addresses."),
        predict:tr!("İşaretsiz yorumda 0xFFFFFFFF mi 2 mi büyük?", "Unsigned: is 0xFFFFFFFF or 2 greater?"),answer:"0xFFFFFFFF",
        change:tr!("bltu'yu blt yapıp sınır durumu dene.","Replace bltu with blt and try the boundary case."),
        task:tr!("a0 ve a1'in işaretsiz büyüğünü a0'da döndür.","Return the unsigned maximum of a0 and a1 in a0."),
        example:"li a0,-1\nli a1,2\nbgeu a0,a1,done\nmv a0,a1\ndone: ebreak\n",starter:"# max_unsigned(a0,a1) -> a0\n\nebreak\n",solution:"bgeu a0,a1,done\nmv a0,a1\ndone: ebreak\n",hint:tr!("bgeu ile kopyalamayı atla.","Use bgeu to skip copying.")},
    Lesson{id:"address",title:tr!("Adres ile değer farklıdır", "Addresses are not contents"),
        about:tr!("la t0,data etiketin adresini koyar. lw a0,0(t0) o adresteki 4 baytı okur. Bellek bayt adreslidir: ikinci kelime +4, üçüncü +8'dir. la ile lw birbirinin yerine geçmez. .word sayıları belleğe koyar; .align 2 sonraki veriyi 4 bayta hizalar.","la t0,data loads a label's address. lw a0,0(t0) reads four bytes there. Memory is byte-addressed: the second word is +4, the third +8. la and lw are not interchangeable. .word puts numbers in memory; .align 2 aligns following data to four bytes."),
        predict:tr!("0x400 adresinden sonraki 32-bit kelimenin adresi?", "Address of the next 32-bit word after 0x400?"),answer:"0x404",
        change:tr!("lw ofsetini 4'ten 8'e çevir.","Change the lw offset from 4 to 8."),
        task:tr!("a0 bir dizinin adresi. İkinci kelimeyi a0'a yükle.","a0 points to an array. Load its second word into a0."),
        example:"la t0,data\nlw a0,4(t0)\nebreak\n.align 2\ndata: .word 7,9,11\n",starter:"# a0 = memory_word[a0 + 4]\n\nebreak\n",solution:"lw a0,4(a0)\nebreak\n",hint:tr!("lw a0,4(a0): adres hesaplanırken eski a0 kullanılır.","lw a0,4(a0): address calculation uses the old a0.")},
    Lesson{id:"store",title:tr!("Belleğe yazma", "Writing memory"),
        about:tr!("sw kaynak,ofset(adres) register'daki değeri RAM'e yazar; hedef register yoktur. lw ile argüman sırasını karıştırma. Örneğin sw a1,4(a0), a0'ı değiştirmez; dört baytı a0+4 adresinden itibaren değiştirir. sb bir bayt yazar, komşu baytları korur.","sw source,offset(address) writes a register to RAM; there is no destination register. Do not confuse its operand order with lw. sw a1,4(a0) preserves a0 and writes four bytes starting at a0+4. sb writes one byte and preserves neighbours."),
        predict:tr!("sw kaç bayt yazar?", "How many bytes does sw write?"),answer:"4",change:tr!("sb kullanınca bellekte kaç bayt değiştiğini izle.","Use sb and inspect how many bytes change."),
        task:tr!("a1 değerini a0 adresindeki dizinin ikinci kelimesine yaz. Diğer iki kelimeyi koru.","Store a1 in the second word of the array at a0. Preserve its other two words."),
        example:"la t0,data\nli a1,42\nsw a1,4(t0)\nebreak\n.align 2\ndata: .word 7,9,11\n",starter:"# word[a0+4] = a1; preserve neighbours\n\nebreak\n",solution:"sw a1,4(a0)\nebreak\n",hint:tr!("sw a1,4(a0). Ofset 1 değil 4.","sw a1,4(a0). The offset is 4, not 1.")},
    Lesson{id:"byte",title:tr!("Bayt ve işaret genişletme", "Bytes and sign extension"),
        about:tr!("Bir bayt 8, register 32 bittir. lb okuduğu baytın bit7'sini üst 24 bite kopyalar; lbu üst bitleri sıfırlar. RAM'deki 0xFF için lb=-1, lbu=255 olur. Ham veri ve UTF-8 için genellikle lbu kullanılır. İşaret genişletme bellekteki baytı değiştirmez.","A byte has 8 bits, a register 32. lb copies bit7 into the upper 24 bits; lbu fills them with zero. For memory byte 0xFF, lb gives -1 and lbu 255. Raw data and UTF-8 usually use lbu. Sign extension does not modify memory."),
        predict:tr!("lbu ile 0xFF okununca onluk sonuç?", "Decimal result of lbu reading 0xFF?"),answer:"255",change:tr!("Aynı adreste lb ve lbu çalıştır; ikilik görünümü aç.","Run lb and lbu at the same address; inspect binary view."),
        task:tr!("a0 adresindeki baytı işaretle genişletip a0'a yükle.","Load the byte at address a0 into a0, sign-extended."),
        example:"la t0,data\nlb a0,0(t0)\nlbu a1,0(t0)\nebreak\ndata: .byte 255\n",starter:"# signed_byte(*a0) -> a0\n\nebreak\n",solution:"lb a0,0(a0)\nebreak\n",hint:tr!("lb kullan; lbu negatif sonuç vermez.","Use lb; lbu cannot produce a negative result.")},
    Lesson{id:"nested",title:tr!("İç içe çağrı ve yığın", "Nested calls and stack"),
        about:tr!("call ra'yı değiştirir. Bir fonksiyon başka fonksiyon çağıracaksa eski ra'yı önce saklamalıdır. Yığın aşağı büyür: sp'yi 16 azalt, sw ra,12(sp), çağrılar, lw ra,12(sp), sp'yi 16 artır, ret. s0–s11 çağıran için korunur; t0–t6 geçicidir. Bu görevde başlangıç sp geçerli verilir; onu eski haline getir.","call overwrites ra. A function calling another must preserve its old ra first. The stack grows downward: subtract 16 from sp, sw ra,12(sp), calls, lw ra,12(sp), restore sp, ret. s0–s11 are callee-saved; t0–t6 temporary. This task provides a valid sp; return it to its original value."),
        predict:tr!("7'ye iki kez 2 eklenirse sonuç?", "Add 2 to 7 twice: result?"),answer:"11",change:tr!("ra kaydetme/yüklemeyi kaldırıp neden dönülemediğini incele.","Remove the ra save/restore and inspect why it cannot return."),
        task:tr!("İç içe iki çağrıyla a0'a 4 ekle. sp ve s0'ı koru; başlangıç kodu ebreak'e dönmeli.","Add 4 to a0 with nested calls. Preserve sp and s0; return to the entry ebreak."),
        example:include_str!("../programs/nested.s"),starter:"call add_four\nebreak\nadd_four:\n# save ra, call add_two twice, restore ra\nret\nadd_two: addi a0,a0,2\nret\n",
        solution:"call add_four\nebreak\nadd_four: addi sp,sp,-16\nsw ra,12(sp)\ncall add_two\ncall add_two\nlw ra,12(sp)\naddi sp,sp,16\nret\nadd_two: addi a0,a0,2\nret\n",hint:tr!("ra'yı yalnızca t register'ında tutmak genel çözüm değildir; alt fonksiyon onu bozabilir.","Keeping ra only in a t register is not a general solution; a callee may overwrite it.")},
    Lesson{id:"echo",title:tr!("Girdi bekleme ve yankı", "Waiting for input and echo"),
        about:tr!("Konsol adresini okumak sıradaki baytı tüketir. Kuyruk boşsa -1 döner: bu bir karakter değildir. -1 ile karşılaştırıp bekle; gerçek karakteri sb ile geri yaz. Enter bu görevde 10'dur. Sayacı olmayan her döngü yanlış değildir: aygıt girdisini bekleme döngüsü normaldir.","Reading the console consumes the next byte. Empty queues return -1, which is not a character. Compare against -1 and wait; write real characters back with sb. Enter is 10 in this task. A loop without a counter may correctly wait for device input."),
        predict:tr!("Tuş yoksa konsol okuması hangi işaretli değeri verir?", "What signed value does an empty console read return?"),answer:"-1",change:tr!("Bekleme kontrolünü kaldır; neden sahte karakter basıldığını gör.","Remove the empty-input check; see why bogus characters appear."),
        task:tr!("Konsoldaki bütün karakterleri Enter dahil geri yaz; sonra dur. Test kuyruğa farklı metinler koyar.","Echo all console bytes including Enter, then stop. Tests enqueue different strings."),
        example:include_str!("../programs/echo.s"),starter:"# read console -> echo until byte 10\n\nebreak\n",solution:include_str!("../programs/echo.s"),hint:tr!("0x10000000'ı lw ile oku, -1 ise döngüye dön. sb ile yaz, 10 ise bitir.","lw from 0x10000000, loop if -1. Print with sb, stop at 10.")},
    Lesson{id:"coordinates",title:tr!("Piksel adresini hesapla", "Calculate a pixel address"),
        about:tr!("Ekran satır satır bellekte tutulur. x sütun, y satırdır: indeks=y×320+x. Her piksel dört bayt olduğu için ofset=indeks×4. Taban 0x11000000 eklenir. İndeksi doğrudan adres gibi kullanmak yanlış yere yazar. Görev koordinatları ekran sınırları içindedir.","The framebuffer is row-major. x is column, y row: index=y×320+x. Each pixel is four bytes, so offset=index×4. Add base 0x11000000. Using the index directly as an address writes to the wrong place. Task coordinates are within screen bounds."),
        predict:tr!("x=1,y=1 için tabana eklenecek bayt ofseti?", "Byte offset from the base for x=1,y=1?"),answer:"1284",change:tr!("x ve y'yi ters çevirip çizimin yerini gözle.","Swap x and y and inspect the drawing location."),
        task:tr!("a0=x,a1=y,a2=renk. Yalnızca bu pikseli boya, ekranı göster ve dur.","a0=x,a1=y,a2=color. Paint only this pixel, present the screen and stop."),
        example:"li a0,1\nli a1,1\nli a2,0x00ff00\nli t0,320\nmul t0,a1,t0\nadd t0,t0,a0\nslli t0,t0,2\nli t1,0x11000000\nadd t0,t0,t1\nsw a2,0(t0)\nli t1,0x1000000c\nsw zero,0(t1)\nebreak\n",starter:"# pixel(a0=x,a1=y)=a2; present\n\nebreak\n",
        solution:"li t0,320\nmul t0,a1,t0\nadd t0,t0,a0\nslli t0,t0,2\nli t1,0x11000000\nadd t0,t0,t1\nsw a2,0(t0)\nli t1,0x1000000c\nsw zero,0(t1)\nebreak\n",hint:tr!("Önce y×320+x, sonra ×4, en son ekran tabanı.","First y×320+x, then ×4, finally add the framebuffer base.")},
]
}
